INSERT INTO brain_facts (id, brain_id, fact_text, fact_type, category, source_type, confidence, is_current, created_at, updated_at) VALUES ('7720ccf5-8d1a-4036-b817-b56bedd224c8', 'edf481c4-5206-4c22-8e82-dbe43f0e4ba3', 'Imported fact', 'custom', 'general', 'manual_entry', 1, TRUE, '2025-10-20T14:10:03.325505+00:00', '2025-10-20T14:10:03.325505+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO brand_rules (id, brain_id, rule_category, rule_type, rule_text, priority, is_active, created_at, updated_at) VALUES ('a21f87d8-d59d-4d9d-8bce-1eb57580e22a', 'dff1217a-a42d-49f6-8496-272d40c34934', 'style', 'voice', '{"tone":"bold and contrarian","avoid":["corporate jargon","buzzwords","excessive politeness"],"style":"no-fluff, direct","audience":"skilled trades professionals"}'::jsonb, 5, TRUE, '2025-10-01T22:02:43.689601+00:00', '2025-10-01T22:02:43.689601+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO brand_rules (id, brain_id, rule_category, rule_type, rule_text, priority, is_active, created_at, updated_at) VALUES ('463194e0-5d1e-432d-b302-193425223967', 'edf481c4-5206-4c22-8e82-dbe43f0e4ba3', 'style', 'voice', '{"title":"Professional & Direct","example":"We will be honest: AI is not magic. It is a tool. Used right, it saves you 10 hours a week.","description":"Our brand voice is professional but never stuffy. We are direct and clear, avoiding corporate jargon. Think trusted advisor not corporate consultant."}'::jsonb, 5, TRUE, '2025-10-20T14:10:03.325505+00:00', '2025-10-20T14:10:03.325505+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO brand_rules (id, brain_id, rule_category, rule_type, rule_text, priority, is_active, created_at, updated_at) VALUES ('fefb866e-460b-4432-922b-271ec16de7d5', 'edf481c4-5206-4c22-8e82-dbe43f0e4ba3', 'style', 'voice', '{"title":"Empowering, Never Condescending","example":"If you are confused by AI, you are not alone. It is overhyped and under-explained. Let us fix that.","description":"We educate and empower, never talk down. Our clients are smart—just busy. We make complex topics accessible without being patronizing."}'::jsonb, 5, TRUE, '2025-10-20T14:10:03.325505+00:00', '2025-10-20T14:10:03.325505+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO brand_rules (id, brain_id, rule_category, rule_type, rule_text, priority, is_active, created_at, updated_at) VALUES ('c0c6e006-2f2a-4704-b337-add706de3832', 'edf481c4-5206-4c22-8e82-dbe43f0e4ba3', 'style', 'voice', '{"title":"Confident But Humble","example":"We have done this 100+ times, and here is what usually works. But every business is different, so we will test and adjust.","description":"We are confident in our expertise but humble about what we do not know. We admit when results take time or when something is not working."}'::jsonb, 5, TRUE, '2025-10-20T14:10:03.325505+00:00', '2025-10-20T14:10:03.325505+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO brand_rules (id, brain_id, rule_category, rule_type, rule_text, priority, is_active, created_at, updated_at) VALUES ('4fd210f4-3df0-43da-b7b8-30d004fdd38c', 'edf481c4-5206-4c22-8e82-dbe43f0e4ba3', 'style', 'voice', '{"title":"Results-Focused, Not Activity-Focused","example":"This campaign generated 47 qualified leads, 12 became customers, contributing $89K in revenue.","description":"We talk about business outcomes (revenue, leads, growth) not marketing activities (posts published, emails sent). We are measured on impact, not effort."}'::jsonb, 5, TRUE, '2025-10-20T14:10:03.325505+00:00', '2025-10-20T14:10:03.325505+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO brand_rules (id, brain_id, rule_category, rule_type, rule_text, priority, is_active, created_at, updated_at) VALUES ('1f22b925-01c3-45f2-96eb-e64e842dc9e5', 'edf481c4-5206-4c22-8e82-dbe43f0e4ba3', 'style', 'tone', '{"title":"Conversational, Not Casual","example":"Here is the thing about SEO... We have seen this before, and here is what works.","description":"We use contractions, ask questions, write like we talk. But we maintain professionalism—no slang, no memes in business contexts."}'::jsonb, 5, TRUE, '2025-10-20T14:10:03.325505+00:00', '2025-10-20T14:10:03.325505+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO brand_rules (id, brain_id, rule_category, rule_type, rule_text, priority, is_active, created_at, updated_at) VALUES ('95cad08e-538f-4d7b-90fc-640416ab7fa9', 'edf481c4-5206-4c22-8e82-dbe43f0e4ba3', 'style', 'tone', '{"title":"Educational, Not Preachy","example":"Most people overthink keyword research. Here is a simpler approach.","description":"We teach useful skills and share insights, but do not lecture. We share here is what works not here is what you should do."}'::jsonb, 5, TRUE, '2025-10-20T14:10:03.325505+00:00', '2025-10-20T14:10:03.325505+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO brand_rules (id, brain_id, rule_category, rule_type, rule_text, priority, is_active, created_at, updated_at) VALUES ('5242e800-c99e-481a-ac5c-ac3d4d0d9b89', 'edf481c4-5206-4c22-8e82-dbe43f0e4ba3', 'style', 'tone', '{"title":"Optimistic But Realistic","example":"Yes, AI can save you time. But it takes 2-3 months to set up properly. SEO works incredibly well—but takes 4-6 months to see major results.","description":"We are positive about possibilities but honest about effort, timelines, challenges. No false promises."}'::jsonb, 5, TRUE, '2025-10-20T14:10:03.325505+00:00', '2025-10-20T14:10:03.325505+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO brand_rules (id, brain_id, rule_category, rule_type, rule_text, priority, is_active, created_at, updated_at) VALUES ('45f411c0-7225-49ba-89f4-5790e88ca649', 'edf481c4-5206-4c22-8e82-dbe43f0e4ba3', 'style', 'style', '{"title":"Short Sentences, Short Paragraphs","description":"Favor readability. Short sentences (10-20 words average). Short paragraphs (2-4 sentences). Bullet points for lists. White space for breathing. This makes content scannable and digestible."}'::jsonb, 5, TRUE, '2025-10-20T14:10:03.325505+00:00', '2025-10-20T14:10:03.325505+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO brand_rules (id, brain_id, rule_category, rule_type, rule_text, priority, is_active, created_at, updated_at) VALUES ('13193825-1cc6-4332-a581-9c09e5cfd8df', 'edf481c4-5206-4c22-8e82-dbe43f0e4ba3', 'style', 'style', '{"good":"We generate leads (not Leads are generated by us). Our AI tools save you time (not Time is saved by our AI tools).","title":"Active Voice Over Passive Voice","description":"Use active voice whenever possible. It is clearer, more direct, more engaging."}'::jsonb, 5, TRUE, '2025-10-20T14:10:03.325505+00:00', '2025-10-20T14:10:03.325505+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO brand_rules (id, brain_id, rule_category, rule_type, rule_text, priority, is_active, created_at, updated_at) VALUES ('acef509d-5bd7-41aa-ac48-7323ae60167a', 'edf481c4-5206-4c22-8e82-dbe43f0e4ba3', 'style', 'style', '{"good":"We increased organic traffic by 247% in 6 months (not massive traffic increase). Generated 89 qualified leads (not lots of leads).","title":"Specific Numbers Over Vague Claims","description":"Use precise numbers, dates, data points instead of vague claims. Specificity builds credibility."}'::jsonb, 5, TRUE, '2025-10-20T14:10:03.325505+00:00', '2025-10-20T14:10:03.325505+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO brand_rules (id, brain_id, rule_category, rule_type, rule_text, priority, is_active, created_at, updated_at) VALUES ('2db2bd4f-7309-475f-876f-6c03ff7650fa', 'edf481c4-5206-4c22-8e82-dbe43f0e4ba3', 'style', 'style', '{"bad":"You Will Not Believe What Happened Next...","good":"AI Cannot Replace Strategic Thinking (And That is Good)","title":"Headers That Tell, Not Tease","description":"Headers should communicate the key point, not create mystery. Scannable content wins."}'::jsonb, 5, TRUE, '2025-10-20T14:10:03.325505+00:00', '2025-10-20T14:10:03.325505+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO brand_rules (id, brain_id, rule_category, rule_type, rule_text, priority, is_active, created_at, updated_at) VALUES ('de9150dc-f88a-487f-a1cb-7fad1e360bd2', 'edf481c4-5206-4c22-8e82-dbe43f0e4ba3', 'style', 'lexicon', '{"title":"Brand-Specific Terms","use_consistently":["Marketing partner (not vendor/agency)","AI automation (not machine learning)","Fractional CMO (not part-time marketing director)","Marketing system (not stack)","Results (not deliverables)","Transparency (core differentiator)","Empower (not enable/facilitate)"]}'::jsonb, 5, TRUE, '2025-10-20T14:10:03.325505+00:00', '2025-10-20T14:10:03.325505+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO brand_rules (id, brain_id, rule_category, rule_type, rule_text, priority, is_active, created_at, updated_at) VALUES ('f47a717e-253c-40be-b5d4-81e7417d8eda', 'edf481c4-5206-4c22-8e82-dbe43f0e4ba3', 'style', 'lexicon', '{"title":"Plain English Over Jargon","simple_words":{"buy":"not purchase/procure","use":"not leverage/utilize","help":"not facilitate/enable","about":"not approximately/circa","improve":"not optimize (unless technical context)"}}'::jsonb, 5, TRUE, '2025-10-20T14:10:03.325505+00:00', '2025-10-20T14:10:03.325505+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO brand_rules (id, brain_id, rule_category, rule_type, rule_text, priority, is_active, created_at, updated_at) VALUES ('6cdf5c28-4444-48ee-bf14-2b64ad5d5513', 'edf481c4-5206-4c22-8e82-dbe43f0e4ba3', 'style', 'lexicon', '{"title":"Define Industry Terms","example":"SEO (search engine optimization)—basically, getting your website to show up on Google. We will improve your CTR (click-through rate)—that is the percentage of people who see your ad and actually click it.","description":"When using industry terms, define them. Never assume everyone knows."}'::jsonb, 5, TRUE, '2025-10-20T14:10:03.325505+00:00', '2025-10-20T14:10:03.325505+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO brand_rules (id, brain_id, rule_category, rule_type, rule_text, priority, is_active, created_at, updated_at) VALUES ('134613f8-794a-4215-b8b8-51a50c4d86ed', 'edf481c4-5206-4c22-8e82-dbe43f0e4ba3', 'style', 'taboos', '{"why":"We build trust through honesty, not excitement.","title":"No Hype or Hyperbole","forbidden":["Revolutionary","Game-changing","Best in the world","Guaranteed results","Explosive growth","Cutting-edge (unless specifically new tech)","Never seen before","Secret formula"],"description":"Avoid exaggerated claims, superlatives."}'::jsonb, 5, TRUE, '2025-10-20T14:10:03.325505+00:00', '2025-10-20T14:10:03.325505+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO brand_rules (id, brain_id, rule_category, rule_type, rule_text, priority, is_active, created_at, updated_at) VALUES ('696c550c-2278-4f46-a402-fe5f99577878', 'edf481c4-5206-4c22-8e82-dbe43f0e4ba3', 'style', 'taboos', '{"why":"Trust is earned through transparency, not demanded through authority.","title":"No Trust Us Without Proof","forbidden":["Just trust us, we are the experts","Our proprietary system works—we cannot explain how","You would not understand the technical details"],"description":"Never ask readers to trust us without backing it up with evidence, examples, logic."}'::jsonb, 5, TRUE, '2025-10-20T14:10:03.325505+00:00', '2025-10-20T14:10:03.325505+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO brand_rules (id, brain_id, rule_category, rule_type, rule_text, priority, is_active, created_at, updated_at) VALUES ('00279061-1c3a-4136-9eed-f8f504fe6063', 'edf481c4-5206-4c22-8e82-dbe43f0e4ba3', 'style', 'taboos', '{"bad":"Our service includes 12 social media posts per month.","good":"We keep your social media active (12 posts/month) so you do not have to.","title":"No Feature Dumping","description":"Do not list features without connecting them to benefits and outcomes. Nobody cares what your service includes—they care what it does for them."}'::jsonb, 5, TRUE, '2025-10-20T14:10:03.325505+00:00', '2025-10-20T14:10:03.325505+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO brand_rules (id, brain_id, rule_category, rule_type, rule_text, priority, is_active, created_at, updated_at) VALUES ('9abc1a28-61a0-40c4-b25d-7ff6895b1177', 'edf481c4-5206-4c22-8e82-dbe43f0e4ba3', 'style', 'taboos', '{"why":"These phrases are lazy and meaningless.","title":"No Corporate Clichés","forbidden":["Think outside the box","Low-hanging fruit","Move the needle","Circle back","Synergy","Best-in-class","Value-add","Next level","Take it offline","Leverage our core competencies"],"description":"Avoid overused business phrases."}'::jsonb, 5, TRUE, '2025-10-20T14:10:03.325505+00:00', '2025-10-20T14:10:03.325505+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO brand_rules (id, brain_id, rule_category, rule_type, rule_text, priority, is_active, created_at, updated_at) VALUES ('74c4dc31-f231-473b-a4b7-f87ac3561dbf', 'edf481c4-5206-4c22-8e82-dbe43f0e4ba3', 'style', 'taboos', '{"bad":"Unlike other agencies who scam you, we are honest.","good":"Here is our approach and why it works.","title":"No Negativity Toward Competitors","description":"We differentiate by highlighting what we do well, not by trashing competitors. Be confident, not petty."}'::jsonb, 5, TRUE, '2025-10-20T14:10:03.325505+00:00', '2025-10-20T14:10:03.325505+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO brand_rules (id, brain_id, rule_category, rule_type, rule_text, priority, is_active, created_at, updated_at) VALUES ('a475f51f-0059-4f3d-bff6-c0b388911311', 'edf481c4-5206-4c22-8e82-dbe43f0e4ba3', 'style', 'taboos', '{"bad":"Only 2 spots left this month! Act now!","good":"We are booking projects for Q2. Want to discuss?","title":"No Fake Urgency","description":"Do not manufacture urgency with countdown timers or false scarcity. If there is a real deadline, state it. Otherwise, do not manipulate."}'::jsonb, 5, TRUE, '2025-10-20T14:10:03.325505+00:00', '2025-10-20T14:10:03.325505+00:00') ON CONFLICT (id) DO NOTHING;
